import{_ as e,c as r,o as i,ah as n}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"43、【夬】 乾下兌上","description":"溫公易說 - 43、【夬】 乾下兌上","frontmatter":{"title":"43、【夬】 乾下兌上","description":"溫公易說 - 43、【夬】 乾下兌上"},"headers":[],"relativePath":"classics/wengong/044.md","filePath":"classics/wengong/044.md"}'),l={name:"classics/wengong/044.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_43、【夬】-乾下兌上" tabindex="-1">43、【夬】 乾下兌上 <a class="header-anchor" href="#_43、【夬】-乾下兌上" aria-label="Permalink to “43、【夬】 乾下兌上”">​</a></h1><h3 id="彖曰-夬-決也。剛決柔也-健而說。決而和-揚於王庭-柔乘五剛也。孚號有厲-其危乃光也。告自邑-不利即戎-所尚乃窮也。利有攸往-剛長乃終也。" tabindex="-1">彖曰：夬，決也。剛決柔也，健而說。決而和，揚於王庭，柔乘五剛也。孚號有厲，其危乃光也。告自邑，不利即戎，所尚乃窮也。利有攸往，剛長乃終也。 <a class="header-anchor" href="#彖曰-夬-決也。剛決柔也-健而說。決而和-揚於王庭-柔乘五剛也。孚號有厲-其危乃光也。告自邑-不利即戎-所尚乃窮也。利有攸往-剛長乃終也。" aria-label="Permalink to “彖曰：夬，決也。剛決柔也，健而說。決而和，揚於王庭，柔乘五剛也。孚號有厲，其危乃光也。告自邑，不利即戎，所尚乃窮也。利有攸往，剛長乃終也。”">​</a></h3><h3 id="象曰-澤上於天-夬。君子以施祿及下-居德則忌。" tabindex="-1">象曰：澤上於天，夬。君子以施祿及下，居德則忌。 <a class="header-anchor" href="#象曰-澤上於天-夬。君子以施祿及下-居德則忌。" aria-label="Permalink to “象曰：澤上於天，夬。君子以施祿及下，居德則忌。”">​</a></h3><h3 id="初九-壯於前趾-往不勝為咎-象曰-不勝而往-咎也。" tabindex="-1">初九：壯於前趾，往不勝為咎 象曰：不勝而往，咎也。 <a class="header-anchor" href="#初九-壯於前趾-往不勝為咎-象曰-不勝而往-咎也。" aria-label="Permalink to “初九：壯於前趾，往不勝為咎 象曰：不勝而往，咎也。”">​</a></h3><h3 id="九二-惕號-莫夜有戎-勿恤-象曰-有戎勿恤-得中道也。" tabindex="-1">九二：惕號，莫夜有戎，勿恤 象曰：有戎勿恤，得中道也。 <a class="header-anchor" href="#九二-惕號-莫夜有戎-勿恤-象曰-有戎勿恤-得中道也。" aria-label="Permalink to “九二：惕號，莫夜有戎，勿恤 象曰：有戎勿恤，得中道也。”">​</a></h3><h3 id="九三-壯於頄-有兇。君子夬夬-獨行遇雨若濡-有慍無咎-象曰-君子夬夬-終無咎也。" tabindex="-1">九三：壯於頄，有兇。君子夬夬，獨行遇雨若濡，有慍無咎 象曰：君子夬夬，終無咎也。 <a class="header-anchor" href="#九三-壯於頄-有兇。君子夬夬-獨行遇雨若濡-有慍無咎-象曰-君子夬夬-終無咎也。" aria-label="Permalink to “九三：壯於頄，有兇。君子夬夬，獨行遇雨若濡，有慍無咎 象曰：君子夬夬，終無咎也。”">​</a></h3><p>壯於頄，壯形於面也。三為健極，故曰壯於頄也。物惡太健，故有兇。然君子居之，體剛履正，決決無疑，信志獨行而不易於世，故雖怨怒不足為咎也。雨濡者，怨謗之象也。</p><h3 id="九四-臀無膚-其行次且。牽羊悔亡-聞言不信-象曰-其行次且-位不當也。聞言不信-聰不明也。" tabindex="-1">九四：臀無膚，其行次且。牽羊悔亡，聞言不信 象曰：其行次且，位不當也。聞言不信，聰不明也。 <a class="header-anchor" href="#九四-臀無膚-其行次且。牽羊悔亡-聞言不信-象曰-其行次且-位不當也。聞言不信-聰不明也。" aria-label="Permalink to “九四：臀無膚，其行次且。牽羊悔亡，聞言不信 象曰：其行次且，位不當也。聞言不信，聰不明也。”">​</a></h3><h3 id="九五-莧陸夬夬-中行無咎-象曰-中行無咎-中未光也。" tabindex="-1">九五：莧陸夬夬，中行無咎 象曰：中行無咎，中未光也。 <a class="header-anchor" href="#九五-莧陸夬夬-中行無咎-象曰-中行無咎-中未光也。" aria-label="Permalink to “九五：莧陸夬夬，中行無咎 象曰：中行無咎，中未光也。”">​</a></h3><h3 id="上六-無號-終有兇-象曰-無號之兇-終不可長也。" tabindex="-1">上六：無號，終有兇 象曰：無號之兇，終不可長也。 <a class="header-anchor" href="#上六-無號-終有兇-象曰-無號之兇-終不可長也。" aria-label="Permalink to “上六：無號，終有兇 象曰：無號之兇，終不可長也。”">​</a></h3>',10)])])}const m=e(l,[["render",t]]);export{b as __pageData,m as default};
